h4=A.Y(u8,1,!0,B.a2,y3,B.lq,u8,"r_softtofu_steamed",A.a([A.j("",50,"softtofu","\uc5f0\ub450\ubd80",u8,!1,u7)],ba0),!1,!1,!1,h4,"\uc5f0\ub450\ubd80 \ucc1c",u8,u8,ap9,B.Z,A.a([A.d("\uc5f0\ub450\ubd80\ub97c \ud1b5\uc9f8\ub85c \ub0b4\uc5f4 \uadf8\ub987\uc5d0 \ub2f4\uace0 \uae40 \uc624\ub978 \ucc1c\uae30\uc5d0 5\ubd84\uac04 \uca84\uc8fc\uc138\uc694. \uac00\uc7a5\uc790\ub9ac\uac00 \uc0b4\uc9dd \ub2e8\ub2e8\ud574\uc9c0\uace0 \ud45c\uba74\uc5d0 \ubb3c\uae30\uac00 \ub9fa\ud788\uba74 \uaebc\ub0b4\uc8fc\uc138\uc694. \ub370\uc6b0\uae30\ub9cc \ud574\ub3c4 \ube44\ub9b0\ub0b4\uac00 \uc904\uace0 \uc18c\ud654\uac00 \ud3b8\ud574\uc838\uc694.",v2,u8,1,"\uadf8\ub987\uc5d0 \ub2f4\uc544 \ucc1c\uae30\uc5d0 5\ubd84 \uca84\uc694.",300),A.d("\ucc0c\uba74\uc11c \ub098\uc628 \ubb3c\uc744 \uc0b4\uc9dd \ub530\ub77c\ub0b4\uace0 3\ubd84 \uc2dd\ud600\uc8fc\uc138\uc694. \uc21f\uac00\ub77d\uc73c\ub85c \ud07c\uc9c1\ud558\uac8c \ub5a0\uc11c \uc8fc\uba74 \uc2a4\uc2a4\ub85c \uba39\uae30 \uc88b\uc544\uc694.",v6,u8,2,"\ub098\uc628 \ubb3c\uc744 \ub530\ub77c\ub0b4\uace0 \uc2dd\ud600\uc694.",180)],ba1),"\uc21f\uac00\ub77d \uc5f0\uc2b5\uc5d0 \uc88b\uc544\uc694. \ubb34\uc5fc \uc81c\ud488\uc778\uc9c0 \uaf2d \ud655\uc778\ud574 \uc8fc\uc138\uc694.",8,u8)
