h6=A.Y(u8,1,!1,B.a2,ac8,B.pm,u8,"r_apple_puree",A.a([A.j("",60,ac6,ac7,u8,!1,u7)],ba0),!1,!1,!1,h6,"\uc0ac\uacfc \ud4e8\ub808",u8,u8,ap9,B.Z,A.a([A.d("\uaecd\uc9c8\uacfc \uc528\ub97c \uc81c\uac70\ud558\uace0 1cm \ud06c\uae30\ub85c \uc370\uc5b4\uc8fc\uc138\uc694.",ab4,u8,1,"\uaecd\uc9c8\uc744 \ubc97\uae30\uace0 \uc798\uac8c \uc370\uc5b4\uc694.",u8),A.d("\ub0c4\ube44\uc5d0 \uc0ac\uacfc\uc640 \ubb3c 2\ud070\uc220\uc744 \ub123\uace0 \ub69c\uaed1\uc744 \ub36e\uc5b4 \uc57d\ubd88\uc5d0\uc11c 8\ubd84\uac04 \uc775\ud600\uc8fc\uc138\uc694. \ud3ec\ud06c\ub85c \ub20c\ub7ec \ubd80\uc11c\uc9c0\uba74 \ub2e4 \ub41c \uac70\uc608\uc694.",v2,u8,2,"\ubb3c\uc744 \uc870\uae08 \ub123\uace0 8\ubd84 \uc775\ud600\uc694.",480),A.d("\ud6c4\uae30\ub294 \ud3ec\ud06c\ub85c \uc0b4\uc9dd \uc73c\uae68 \ub369\uc5b4\ub9ac\ub97c \ub0a8\uae30\uace0, \uc544\uc9c1 \ub369\uc5b4\ub9ac\ub97c \ud798\ub4e4\uc5b4\ud558\uba74 \uacf1\uac8c \uac08\uc544\uc8fc\uc138\uc694.",w7,u8,3,"\uc73c\uae68\uac70\ub098 \uacf1\uac8c \uac08\uc544\uc694.",u8)],ba1),ak5,12,u8)
